changed = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Step 2: For each changed pair, find minimal edit
print("\nMinimal edits:")
for idx, inp, outp in changed:
    # Simple approach: find first differing character
    min_len = min(len(inp), len(outp))
    pos = -1
    for i in range(min_len):
        if inp[i] != outp[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(inp) < len(outp):
            pos = len(inp)
        else:
            pos = len(outp)

    if pos >= 0:
        old_char = inp[pos] if pos < len(inp) else ""
        new_char = outp[pos] if pos < len(outp) else ""
        print(f"  {idx}: pos {pos}, '{old_char}' -> '{new_char}'")

